
!(function () {
    'use strict';

    // Tooltips
    let tooltipTriggerList = [].slice.call(
        document.querySelectorAll('[data-bs-toggle="tooltip"]')
    );
    tooltipTriggerList.map(function (tooltipTriggerEl) {
        return new bootstrap.Tooltip(tooltipTriggerEl);
    });

    const isMobile =
        /android|webos|iphone|ipad|ipod|blackberry|iemobile|opera mini/i.test(
            navigator.userAgent.toLowerCase()
        );


    // cuando el dom este listo (Esto solo funciona en desktop)
    document.onreadystatechange = () => {
        if (document.readyState === "complete") {
            // escuchamos los eventos
            listen(document.getElementById("name"), "Escriba su nombre para saber a quien nos dirijirnos");
            listen(document.getElementById("email"), "Necesitamos que nos proporcione un correo valido");
            listen(
                document.getElementById("phone"),
                "Necesitamos que nos proporcione un numero de telefono valido para poder llamarle"
            );
            listen(document.getElementById("subject"), "Necesitamos que nos proporcione asunto valido");
            listen(document.getElementById("message"), "Necesitamos que nos proporcione un mensaje");
            listen(document.getElementById("captcha"), "Necesitamos que nos proporcione un codigo valido");
        }
    };

    // function para escuchar eventos invalid y input
    function listen(uid, txt) {
        uid && uid.addEventListener("invalid", (evt) => isInValidInput(evt, txt));
        uid && uid.addEventListener("input", (evt) => isValidInput(evt));
    }
    // No es valido
    function isInValidInput(evt, txt) {
        evt.target.className = "is-invalid form-control";
        evt.target.setCustomValidity(txt);
    }
    // Es valido
    function isValidInput(evt) {
        evt.target.className = "form-control";
        evt.target.setCustomValidity("");
    }

})();